--   SAT_PROVIDER_QUALITY
--   anchor      : HUB_PARTY
--   grain       : SCD2 (data_7.js sats[].hist)
--   child key   : (none declared)
--   feeders     : 3 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PARTY_BK__K4)) as HUB_PARTY_HK,
        HOSPITAL_GRADE as QUALITY_RATING,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIMDETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clmdetail_apv') }}
    where HUB_PARTY_K4__EMIT
    union all
    select
        md5(upper(HUB_PARTY_BK__K1)) as HUB_PARTY_HK,
        OVERALL_RATING as QUALITY_RATING,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_ppd_pv') }}
    where HUB_PARTY_K1__EMIT
    union all
    select
        md5(upper(HUB_PARTY_BK__K2)) as HUB_PARTY_HK,
        OVERALL_RATING as QUALITY_RATING,
        'MAXI_HLTH_UWR_VW_DATA_RELATIONS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_relations_ppd_pv') }}
    where HUB_PARTY_K2__EMIT
)), hashed as (select *,
        case when QUALITY_RATING is not null
             then md5(upper(coalesce(QUALITY_RATING::varchar,'')))
        end as SAT_PROVIDER_QUALITY_HASHDIFF
    from feeders)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PROVIDER_QUALITY_HASHDIFF is not null
